function verticalOffset(radius: number, angle: number): number {
  return radius * math.sin(angle);
}

function horizontalOffset(radius: number, angle: number): number {
  return radius * math.cos(angle);
}

function headingRadians(dx: number, dy: number): number {
  return math.atan2(dy, dx);
}

function headingDegrees(dx: number, dy: number): number {
  return math.atan2(dy, dx) * 180 / math.pi();
}

function rootMeanSquare(a: number, b: number): number {
  return math.sqrt((a * a + b * b) / 2);
}

function compoundAmount(principal: number, rate: number, periods: number): number {
  return principal * math.pow(1 + rate, periods);
}

function pageCount(items: number, pageSize: number): number {
  return math.ceil(items / pageSize);
}

function completeGroups(items: number, groupSize: number): number {
  return math.floor(items / groupSize);
}

function roundToStep(value: number, step: number): number {
  return math.round(value / step) * step;
}

function absoluteGap(a: number, b: number): number {
  return math.abs(a - b);
}

function boundedValue(value: number, lower: number, upper: number): number {
  return math.min(math.max(value, lower), upper);
}

function advanceSeed(seed: number): number {
  return math.randomStep(seed);
}

function bucketForSeed(seed: number, bound: number): number {
  return math.randomBelow(seed, bound);
}

function characterCount(text: string): number {
  return strings.length(text);
}

function characterWindow(text: string, start: number, end: number): string {
  return strings.substring(text, start, end);
}

function containsText(text: string, needle: string): boolean {
  return strings.contains(text, needle);
}

function hasPrefix(text: string, needle: string): boolean {
  return strings.startsWith(text, needle);
}

function hasSuffix(text: string, needle: string): boolean {
  return strings.endsWith(text, needle);
}

function replaceLiteralAll(text: string, search: string, replacement: string): string {
  return strings.replace(text, search, replacement);
}

function splitLiteral(text: string, separator: string): string[] {
  return strings.split(text, separator);
}

function trimUnicodeSpace(text: string): string {
  return strings.trim(text);
}

function uppercaseText(text: string): string {
  return strings.toUpperCase(text);
}

function lowercaseText(text: string): string {
  return strings.toLowerCase(text);
}

function parseTypedDecimal(text: string, fallback: number): number {
  return strings.toNumber(text, fallback);
}

function prefixCharacters(text: string, count: number): string {
  return strings.substring(text, 0, math.min(count, strings.length(text)));
}

function suffixCharacters(text: string, count: number): string {
  let size: number = strings.length(text);
  return strings.substring(text, math.max(0, size - count), size);
}

function windowByCount(text: string, start: number, count: number): string {
  return strings.substring(text, start, math.min(strings.length(text), start + count));
}

function removePrefixOnce(text: string, affix: string): string {
  if (strings.startsWith(text, affix)) { return strings.substring(text, strings.length(affix), strings.length(text)); }
  return text;
}

function removeSuffixOnce(text: string, affix: string): string {
  if (strings.endsWith(text, affix)) { return strings.substring(text, 0, strings.length(text) - strings.length(affix)); }
  return text;
}

function ensurePrefix(text: string, prefix: string): string {
  if (strings.startsWith(text, prefix)) { return text; }
  return prefix + text;
}

function ensureSuffix(text: string, suffix: string): string {
  if (strings.endsWith(text, suffix)) { return text; }
  return text + suffix;
}

function enclosedText(text: string, opening: string, closing: string): boolean {
  return strings.startsWith(text, opening) && strings.endsWith(text, closing) && strings.length(text) >= strings.length(opening) + strings.length(closing);
}

function unwrapText(text: string, opening: string, closing: string): string {
  let size: number = strings.length(text);
  let left: number = strings.length(opening);
  let right: number = strings.length(closing);
  if (size >= left + right && strings.startsWith(text, opening) && strings.endsWith(text, closing)) { return strings.substring(text, left, size - right); }
  return text;
}

function shortenWithMarker(text: string, limit: number, marker: string): string {
  if (strings.length(text) <= limit) { return text; }
  return strings.substring(text, 0, limit - strings.length(marker)) + marker;
}

function replaceInsideWindow(text: string, start: number, end: number, search: string, replacement: string): string {
  return strings.substring(text, 0, start) + strings.replace(strings.substring(text, start, end), search, replacement) + strings.substring(text, end, strings.length(text));
}

function replaceInOrder(text: string, first: string, second: string, replacement: string): string {
  return strings.replace(strings.replace(text, first, replacement), second, replacement);
}

function replaceFirstLiteral(text: string, search: string, replacement: string): string {
  let width: number = strings.length(search);
  let size: number = strings.length(text);
  let position: number = 0;
  while (position + width <= size) {
    if (strings.substring(text, position, position + width) === search) { return strings.substring(text, 0, position) + replacement + strings.substring(text, position + width, size); }
    position = position + 1;
  }
  return text;
}

function literalOccurrenceCount(text: string, search: string): number {
  return strings.split(text, search).length() - 1;
}

function containsAfterLowercase(text: string, query: string): boolean {
  return strings.contains(strings.toLowerCase(text), strings.toLowerCase(query));
}

function trimmedLowercase(text: string): string {
  return strings.toLowerCase(strings.trim(text));
}

function trimmedUppercase(text: string): string {
  return strings.toUpperCase(strings.trim(text));
}

function blankOrFallback(text: string, fallback: string): string {
  let cleaned: string = strings.trim(text);
  if (strings.length(cleaned) === 0) { return fallback; }
  return cleaned;
}

function trimmedLength(text: string): number {
  return strings.length(strings.trim(text));
}

function uppercaseLength(text: string): number {
  return strings.length(strings.toUpperCase(text));
}

function fieldAt(text: string, separator: string, index: number, fallback: string): string {
  let fields: string[] = strings.split(text, separator);
  if (index < 0 || index >= fields.length()) { return fallback; }
  return fields[index];
}

function fieldCount(text: string, separator: string): number {
  return strings.split(text, separator).length();
}

function trimmedFields(text: string, separator: string): string[] {
  let fields: string[] = strings.split(text, separator);
  let result: string[] = [];
  for (let field: string of fields) { result.push(strings.trim(field)); }
  return result;
}

function nonblankFields(text: string, separator: string): string[] {
  let result: string[] = [];
  for (let field: string of strings.split(text, separator)) {
    let cleaned: string = strings.trim(field);
    if (strings.length(cleaned) > 0) { result.push(cleaned); }
  }
  return result;
}

function joinFieldsWith(text: string, separator: string, joiner: string): string {
  let fields: string[] = strings.split(text, separator);
  let result: string = "";
  let index: number = 0;
  while (index < fields.length()) {
    if (index > 0) { result = result + joiner; }
    result = result + fields[index];
    index = index + 1;
  }
  return result;
}

function lastPathSegment(path: string): string {
  let segments: string[] = strings.split(path, "/");
  return segments[segments.length() - 1];
}

function parentPathText(path: string): string {
  let segments: string[] = strings.split(path, "/");
  let result: string = "";
  let index: number = 0;
  while (index + 1 < segments.length()) {
    if (index > 0) { result = result + "/"; }
    result = result + segments[index];
    index = index + 1;
  }
  return result;
}

function filenameMatchesExtension(filename: string, extension: string): boolean {
  return strings.endsWith(strings.toLowerCase(filename), strings.toLowerCase(extension));
}

function replacePathSeparator(path: string, oldSeparator: string, newSeparator: string): string {
  return strings.replace(path, oldSeparator, newSeparator);
}

function redactToken(text: string, token: string, mask: string): string {
  return strings.replace(text, token, mask);
}

function replacePlaceholder(template: string, placeholder: string, value: string): string {
  return strings.replace(template, placeholder, value);
}

function surroundMatches(text: string, search: string, opening: string, closing: string): string {
  return strings.replace(text, search, opening + search + closing);
}

function firstMatchPosition(text: string, query: string): number {
  let index: number = 0;
  let width: number = strings.length(query);
  let size: number = strings.length(text);
  while (index + width <= size) {
    if (strings.substring(text, index, index + width) === query) { return index; }
    index = index + 1;
  }
  return -1;
}

function lastMatchPosition(text: string, query: string): number {
  let index: number = strings.length(text) - strings.length(query);
  while (index >= 0) {
    if (strings.substring(text, index, index + strings.length(query)) === query) { return index; }
    index = index - 1;
  }
  return -1;
}

function textBeforeDelimiter(text: string, delimiter: string): string {
  let parts: string[] = strings.split(text, delimiter);
  return parts[0];
}

function textAfterDelimiter(text: string, delimiter: string): string {
  let parts: string[] = strings.split(text, delimiter);
  if (parts.length() === 1) { return ""; }
  return strings.substring(text, strings.length(parts[0]) + strings.length(delimiter), strings.length(text));
}

function signedDeviation(observed: number, target: number): number {
  return observed - target;
}

function withinTolerance(observed: number, target: number, tolerance: number): boolean {
  return math.abs(observed - target) <= tolerance;
}

function clampedFraction(value: number, lower: number, upper: number): number {
  return math.min(1, math.max(0, (value - lower) / (upper - lower)));
}

function interpolateClamped(start: number, stop: number, fraction: number): number {
  let progress: number = math.min(1, math.max(0, fraction));
  return start + (stop - start) * progress;
}

function roundUpToStep(value: number, step: number): number {
  return math.ceil(value / step) * step;
}

function roundDownToStep(value: number, step: number): number {
  return math.floor(value / step) * step;
}

function decimalRounding(value: number, digits: number): number {
  let factor: number = math.pow(10, digits);
  return math.round(value * factor) / factor;
}

function remainingCapacity(capacity: number, used: number): number {
  return math.max(capacity - used, 0);
}

function overLimitAmount(used: number, limit: number): number {
  return math.max(used - limit, 0);
}

function batchesWithReserve(items: number, reserve: number, batchSize: number): number {
  return math.ceil((items + reserve) / batchSize);
}

function pageOffset(page: number, pageSize: number): number {
  return (page - 1) * pageSize;
}

function lastPageItems(items: number, pageSize: number): number {
  if (items === 0) { return 0; }
  return items - (math.ceil(items / pageSize) - 1) * pageSize;
}

function distanceBetweenPoints(x1: number, y1: number, x2: number, y2: number): number {
  let dx: number = x2 - x1;
  let dy: number = y2 - y1;
  return math.sqrt(dx * dx + dy * dy);
}

function polarXDegrees(radius: number, degrees: number): number {
  return radius * math.cos(degrees * math.pi() / 180);
}

function polarYDegrees(radius: number, degrees: number): number {
  return radius * math.sin(degrees * math.pi() / 180);
}

function circleArea(radius: number): number {
  return math.pi() * radius * radius;
}

function circleCircumference(radius: number): number {
  return 2 * math.pi() * radius;
}

function decayedAmount(initial: number, retention: number, periods: number): number {
  return initial * math.pow(retention, periods);
}

function growthDifference(initial: number, rate: number, periods: number): number {
  return initial * math.pow(1 + rate, periods) - initial;
}

function parseThenClamp(text: string, fallback: number, lower: number, upper: number): number {
  return math.min(upper, math.max(lower, strings.toNumber(text, fallback)));
}

function parseThenScale(text: string, fallback: number, factor: number): number {
  return strings.toNumber(text, fallback) * factor;
}

function valuesWithinBounds(values: number[], lower: number, upper: number): number[] {
  let result: number[] = [];
  for (let value: number of values) { if (value >= lower && value <= upper) { result.push(value); } }
  return result;
}

function countWithinBounds(values: number[], lower: number, upper: number): number {
  let count: number = 0;
  for (let value: number of values) { if (value >= lower && value <= upper) { count = count + 1; } }
  return count;
}

function clampEachValue(values: number[], lower: number, upper: number): number[] {
  let result: number[] = [];
  for (let value: number of values) { result.push(math.min(math.max(value, lower), upper)); }
  return result;
}

function roundEachValue(values: number[], step: number): number[] {
  let result: number[] = [];
  for (let value: number of values) { result.push(math.round(value / step) * step); }
  return result;
}

function absoluteDifferences(values: number[], target: number): number[] {
  let result: number[] = [];
  for (let value: number of values) { result.push(math.abs(value - target)); }
  return result;
}

function sumAbsoluteDifferences(values: number[], target: number): number {
  let total: number = 0;
  for (let value: number of values) { total = total + math.abs(value - target); }
  return total;
}

function maximumOrFallback(values: number[], fallback: number): number {
  if (values.length() === 0) { return fallback; }
  let best: number = values[0];
  for (let value: number of values) { best = math.max(best, value); }
  return best;
}

function minimumOrFallback(values: number[], fallback: number): number {
  if (values.length() === 0) { return fallback; }
  let best: number = values[0];
  for (let value: number of values) { best = math.min(best, value); }
  return best;
}

function valueRange(values: number[]): number {
  if (values.length() === 0) { return 0; }
  let lo: number = values[0];
  let hi: number = values[0];
  for (let value: number of values) { lo = math.min(lo, value); hi = math.max(hi, value); }
  return hi - lo;
}

function numericFields(text: string, separator: string, fallback: number): number[] {
  let result: number[] = [];
  for (let field: string of strings.split(text, separator)) { result.push(strings.toNumber(field, fallback)); }
  return result;
}

function sumNumericFields(text: string, separator: string, fallback: number): number {
  let total: number = 0;
  for (let field: string of strings.split(text, separator)) { total = total + strings.toNumber(field, fallback); }
  return total;
}

function lengthsOfFields(text: string, separator: string): number[] {
  let result: number[] = [];
  for (let field: string of strings.split(text, separator)) { result.push(strings.length(field)); }
  return result;
}

function matchingFields(text: string, separator: string, query: string): string[] {
  let result: string[] = [];
  for (let field: string of strings.split(text, separator)) { if (strings.contains(field, query)) { result.push(field); } }
  return result;
}

function firstMatchingField(text: string, separator: string, query: string, fallback: string): string {
  for (let field: string of strings.split(text, separator)) { if (strings.contains(field, query)) { return field; } }
  return fallback;
}

function seedBucketAfterStep(seed: number, bound: number): number {
  return math.randomBelow(math.randomStep(seed), bound);
}

function seedSequence(seed: number, count: number): number[] {
  let state: number = seed;
  let result: number[] = [];
  let index: number = 0;
  while (index < count) { state = math.randomStep(state); result.push(state); index = index + 1; }
  return result;
}
